      gateNode, processNode, reviewNode, notifyNode,
      { id: 'done', type: 'end', result: 'finished' },
    ],
  };

  const first = executeWorkflow(workflow, { approved: true });
  assert.deepEqual(first.trace.map(node => node.nodeId),
    ['start', 'gate', 'process', 'done']);

