  validateWorkflow(workflow);
  const second = executeWorkflow(workflow, { approved: true });
  assert.equal(second.status, 'completed');
  assert.deepEqual(second.trace.map(node => node.nodeId),
    ['start', 'gate', 'notify', 'done']);
});

